    else choice(n − 1)
}

def handledChoice(n) {
    handle flip = Flip((), k) ⇒ append(do k(True), do k(False)) in
    handle fail = Fail((), k) ⇒ Nil in
    Cons(choice[lift flip, fail](n), Nil)
}

int choice(bool (flip_func)(*int), void (fail_func)(*int), int* arr, int n) {
    if (n < 1) {
        fail_func(arr);
    } else if (flip_func(arr)) {
        return n;
    } else {
        return choice(flip_func, fail_func, arr, n - 1);
    }
}

